import{emptySchedule,secureURL,dateKey,addDays,monday,validate,sampleSchedule}from'./logic.js';
const $=s=>document.querySelector(s),app=$('#app');const today=dateKey(),sample=emptySchedule();let confirmed=emptySchedule(),scheduleInfo=null,preview=false,studioFilter='all',selected=today,week=monday(today),mode='week',tab='schedule';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(key,opts)=>new Intl.DateTimeFormat('en-US',{timeZone:'UTC',...opts}).format(new Date(key+'T12:00:00Z'));
const time=t=>{const[h,m]=t.split(':').map(Number);return`${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`};
const data=()=>preview?sample:confirmed;
const classTime=c=>time(c.start)+(c.end?' – '+time(c.end):'');
const color=s=>/^#[0-9a-f]{6}$/i.test(s?.colorHex)?s.colorHex:'#a2af91';
function notice(){if(!preview&&scheduleInfo)return `<div class="schedule-intro"><div><p class="eyebrow">Teaching at Eri-Core</p><strong>Find your rhythm.</strong><p>Weekly classes from November 2, 2026. All times Central.</p></div><div class="weekly-times"><span><b>MON</b> 5 &amp; 6 AM</span><span><b>WED</b> 5 AM</span><span><b>FRI</b> 6:30 &amp; 7:30 PM</span><span><b>SUN</b> 9 AM</span></div><div class="schedule-footnote">No Monica classes November 13–15. Times supplied by Monica; confirm availability on the studio timetable. <a href="https://www.eri-corestudio.com/#comp-mo3kn43k" target="_blank" rel="noopener noreferrer">Open Eri-Core’s timetable ↗</a></div></div>`;return ''}
function card(c){const s=data().studios.find(s=>s.id===c.studioID);return`<article class="class-card ${c.cancelled?'cancelled':''}"><div class="studio-tag"><span class="color-dot" style="background:${color(s)}"></span>${esc(s.name)}</div><h3>${esc(c.title)}</h3><p class="class-meta">◷ &nbsp; ${classTime(c)}</p><p class="class-meta">⌖ &nbsp; ${esc(s.area||s.address||'Location to be confirmed')}</p><div class="card-bottom">${c.cancelled?'<span class="cancel-label">Cancelled</span>':`<span class="pill">${esc(c.format)} · With Monica</span>`}<button class="circle-button" data-class="${esc(c.id)}" aria-label="View ${esc(c.title)} at ${esc(s.name)}">↗</button></div></article>`}
function empty(message='No classes on this day',description='Try another day or studio to find a class that fits your week.'){return`<div class="empty"><span style="font-size:30px">▦</span><h3>${message}</h3><p>${description}</p>${!preview&&!confirmed.classes.length?'<a class="primary" href="https://www.eri-corestudio.com/#comp-mo3kn43k" target="_blank" rel="noopener noreferrer">Check Eri-Core’s timetable ↗</a>':'<button class="secondary" data-action="upcoming">See upcoming classes ↗</button>'}</div>`}
function render(){document.querySelectorAll('[data-tab]').forEach(a=>{a.classList.toggle('active',a.dataset.tab===tab);if(a.dataset.tab===tab)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});
 if(tab==='schedule')renderSchedule();else if(tab==='studios')renderStudios();else renderAbout();
}
function renderSchedule(){const schedule=data();const weekDays=Array.from({length:7},(_,i)=>addDays(week,i));let list=schedule.classes.filter(c=>(studioFilter==='all'||c.studioID===studioFilter)&&(mode==='week'?c.date===selected:c.date>=today)).sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start));
 let last='';let cards=list.map(c=>{let heading='';if(mode==='upcoming'&&last!==c.date){last=c.date;heading=`<h3 class="section-date">${fmt(c.date,{weekday:'long',month:'short',day:'numeric'})}</h3>`}return heading+card(c)}).join('');
 app.innerHTML=`<section class="hero"><div><p class="eyebrow">Same Moni. Different studios.</p><h1>Meet me<br>on the <em>mat.</em></h1><p class="description">Find your next Pilates class, wherever I’m teaching.<br>A little movement. A moment for you.</p></div><div class="hero-art photo"><img src="./assets/monica-felan.jpg" alt="Monica, your Pilates instructor" width="1206" height="1396" fetchpriority="high"></div></section><section class="content" aria-label="Class calendar">${notice()}<div class="calendar-toolbar"><div class="segments" aria-label="Schedule view"><button data-mode="week" class="${mode==='week'?'active':''}" aria-pressed="${mode==='week'}">This week</button><button data-mode="upcoming" class="${mode==='upcoming'?'active':''}" aria-pressed="${mode==='upcoming'}">Upcoming</button></div><div class="month-nav"><span class="month-label">${fmt(week,{month:'long',year:'numeric'})}</span><button data-shift="-7" aria-label="Previous week">‹</button><button class="today" data-action="today">Today</button><button data-shift="7" aria-label="Next week">›</button></div></div>${mode==='week'?`<div class="days" aria-label="Choose a day">${weekDays.map(k=>`<button class="day ${k===selected?'selected':''} ${k===today?'current':''}" data-day="${k}" aria-label="${fmt(k,{weekday:'long',month:'long',day:'numeric'})}" aria-pressed="${k===selected}"><small>${fmt(k,{weekday:'short'}).toUpperCase()}</small><span class="day-number">${Number(k.slice(-2))}</span><span class="dot ${schedule.classes.some(c=>c.date===k&&!c.cancelled)?'':'none'}"></span></button>`).join('')}</div>`:''}<div class="filters"><div class="chips" aria-label="Filter by studio"><button class="chip ${studioFilter==='all'?'active':''}" data-studio="all" aria-pressed="${studioFilter==='all'}">All studios</button>${schedule.studios.map(s=>`<button class="chip ${studioFilter===s.id?'active':''}" data-studio="${esc(s.id)}" aria-pressed="${studioFilter===s.id}"><span class="color-dot" style="background:${color(s)}"></span>${esc(s.name)}</button>`).join('')}</div><span class="timezone">All times Central · America/Chicago</span></div><div class="schedule-heading"><h2>${mode==='week'?fmt(selected,{weekday:'long',month:'short',day:'numeric'}):'A little movement, ahead.'}</h2><span>${list.length} ${list.length===1?'class':'classes'}${preview?' · Sample':''}</span></div><div class="class-grid">${cards||(!preview&&!confirmed.classes.length?empty('The schedule is coming soon','Eri-Core classes begin November 2. Check Upcoming to see Monica’s teaching times.'):empty())}</div><div class="week-note"><span>All times Central · Bookings are handled by each studio.</span><a href="#studios">Find your studio ↗</a></div></section>`;
}
function renderStudios(){app.innerHTML=`<section class="content"><div class="page-heading"><p class="eyebrow">Find your space</p><h1>Different studios.<br><em>Same energy.</em></h1><p>One familiar face, wherever you roll out your mat.</p></div>${notice()}<div class="studio-grid">${data().studios.map((s,i)=>`<article class="studio-card">${s.id==='eri-core'?`<div class="studio-art studio-photo"><img src="./assets/eri-core-studio.png" alt="Inside Eri-Core Studio, with Pilates mats and wall-mounted equipment" width="1000" height="1333" loading="lazy"></div>`:`<div class="studio-art" style="background:${color(s)}55" aria-hidden="true"><span>${['flow.','form.','still.'][i%3]}</span></div>`}<div class="studio-info"><p class="eyebrow">${preview?'Sample studio':'Teaching location'}</p><h2>${esc(s.name)}</h2><p>⌖ &nbsp; ${esc(s.address||s.area||'Location to be confirmed')}</p><button class="secondary" data-view-studio="${esc(s.id)}">View Monica’s classes ↗</button>${!preview&&secureURL(s.bookingURL)?`<p><a href="${esc(secureURL(s.bookingURL))}" target="_blank" rel="noopener noreferrer">Studio website ↗</a></p>`:''}</div></article>`).join('')||empty('Studios coming soon','Monica is currently teaching at Eri-Core Studio in Houston.')}</div></section>`}
function renderAbout(){app.innerHTML=`<section class="content about"><div class="portrait"><img src="./assets/monica-felan.jpg" alt="Monica smiling" width="1206" height="1396"></div><div><p class="eyebrow">A little about me</p><h1>Hi, I’m<br><em>Monica.</em></h1><p>I’m your Pilates instructor. This is the place to find my classes as I teach across different studios.</p><p>Choose a class that fits your week, then book with the studio hosting it. I’ll meet you on the mat.</p><div class="benefits">▦ &nbsp; One schedule. All my studios.<br>↗ &nbsp; Book directly with each studio.<br>◉ &nbsp; No client account needed.</div><a class="primary" href="#schedule">Find your next class ↗</a><p class="privacy">Your privacy matters. This app has no analytics or payment collection. Studio booking websites have their own privacy policies.</p></div></section>`}
function showClass(id){const c=data().classes.find(c=>c.id===id);if(!c)return;const s=data().studios.find(s=>s.id===c.studioID),url=secureURL(c.bookingURL||s.bookingURL);$('#detailContent').innerHTML=`<p class="eyebrow">${esc(s.name)}</p><h2>${esc(c.title)}</h2><div class="detail-facts">▦ &nbsp; ${fmt(c.date,{weekday:'long',month:'long',day:'numeric',year:'numeric'})}<br>◷ &nbsp; ${classTime(c)} Central<br>⌖ &nbsp; ${esc(s.address||s.area||'Location to be confirmed')}<br>✦ &nbsp; ${esc(c.format)} · Class details on studio timetable${!c.end?'<br>Duration: to be confirmed by the studio':''}</div>${c.notes?`<p>${esc(c.notes)}</p>`:''}${preview?'<div class="sample-callout">Design preview only. This is a fictional class; booking and calendar saving are disabled.</div>':c.cancelled?'<div class="sample-callout">This class has been cancelled. Please choose another class.</div>':`${url?`<a class="primary" href="${esc(url)}" target="_blank" rel="noopener noreferrer">Book on the studio website ↗</a>`:'<p>Booking link coming soon.</p>'}${c.end?'<button class="secondary" id="calendarSave">Add to calendar ↓</button>':'<p class="fine">Calendar download will be available once the class end time is confirmed.</p>'}${s.address?`<a class="secondary" href="https://maps.apple.com/?q=${encodeURIComponent(s.address)}" target="_blank" rel="noopener noreferrer">Get directions ↗</a>`:''}<p class="fine">Opening the studio website does not reserve a place. Complete your booking there.</p>`}`;$('#calendarSave')?.addEventListener('click',()=>saveCalendar(c,s));$('#details').showModal()}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function saveCalendar(c,s){if(preview||c.cancelled||!c.end)return;const clean=s=>String(s).replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const value=(date,time)=>date.replace(/-/g,'')+'T'+time.replace(':','')+'00';const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Moni//Studio Calendar//EN','BEGIN:VTIMEZONE','TZID:America/Chicago','BEGIN:DAYLIGHT','DTSTART:20070311T020000','RRULE:FREQ=YEARLY;BYMONTH=3;BYDAY=2SU','TZOFFSETFROM:-0600','TZOFFSETTO:-0500','TZNAME:CDT','END:DAYLIGHT','BEGIN:STANDARD','DTSTART:20071104T020000','RRULE:FREQ=YEARLY;BYMONTH=11;BYDAY=1SU','TZOFFSETFROM:-0500','TZOFFSETTO:-0600','TZNAME:CST','END:STANDARD','END:VTIMEZONE','BEGIN:VEVENT',`UID:${crypto.randomUUID()}@moni`, `DTSTAMP:${stamp}`,`DTSTART;TZID=America/Chicago:${value(c.date,c.start)}`,`DTEND;TZID=America/Chicago:${value(c.date,c.end)}`,`SUMMARY:${clean(c.title+' with Monica')}`,`LOCATION:${clean(s.name+(s.address?', '+s.address:''))}`,`DESCRIPTION:${clean('Check the studio website for booking and changes. '+(secureURL(c.bookingURL||s.bookingURL)||''))}`,'END:VEVENT','END:VCALENDAR'];download(lines.join('\r\n')+'\r\n','moni-class.ics','text/calendar')}
function switchData(value){preview=value;studioFilter='all';render()}
app.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.class)showClass(el.dataset.class);else if(el.dataset.day){selected=el.dataset.day;render()}else if(el.dataset.mode){mode=el.dataset.mode;render()}else if(el.dataset.shift){week=addDays(week,Number(el.dataset.shift));selected=addDays(selected,Number(el.dataset.shift));mode='week';render()}else if(el.dataset.studio){studioFilter=el.dataset.studio;render()}else if(el.dataset.viewStudio){studioFilter=el.dataset.viewStudio;mode='upcoming';location.hash='schedule';tab='schedule';render();window.scrollTo(0,0)}else if(el.dataset.action==='today'){week=monday(today);selected=today;mode='week';render()}else if(el.dataset.action==='upcoming'){mode='upcoming';render()}else if(el.dataset.action==='samples')switchData(true);else if(el.dataset.action==='confirmed')switchData(false);});
document.querySelectorAll('dialog .close').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
function route(){const next=location.hash.slice(1);tab=['schedule','studios','moni'].includes(next)?next:'schedule';render();window.scrollTo(0,0)}window.addEventListener('hashchange',route);route();
Promise.all([fetch('./schedule.json',{cache:'no-cache'}).then(r=>{if(!r.ok)throw Error();return r.json()}),fetch('./schedule-info.json',{cache:'no-cache'}).then(r=>r.ok?r.json():null)]).then(([raw,info])=>{scheduleInfo=info;{confirmed=validate(raw);preview=false;const upcoming=confirmed.classes.filter(c=>c.date>=today&&!c.cancelled).sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start));if(upcoming.length&&!confirmed.classes.some(c=>c.date===selected)){selected=upcoming[0].date;week=monday(selected)}render()}}).catch(()=>{app.insertAdjacentHTML('afterbegin','<p class="load-error" role="alert">The shared schedule could not be loaded. Please refresh to try again. <a href="https://www.eri-corestudio.com/" target="_blank" rel="noopener noreferrer">Check Eri-Core’s timetable ↗</a></p>')});
